namespace sv_de6c4f9e784b43849df542f5cf5d5a71.Services;

public record TaskItem(int Id, string Title, string Assignee, string Priority, DateTime DueDate, string Status);

public interface ITaskService
{
    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

@page "/board"
@using sv_de6c4f9e784b43849df542f5cf5d5a71.Services
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h1 class="mb-4">Project Board</h1>

@if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_errorMessage
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <!-- Stats Bar -->
    <div class="row g-2 mb-3">
        <div class="col">
            <div class="card text-center">
                <div class="card-body py-2">
                    <div class="fw-bold">Total</div>
                    <div class="fs-5">@_allTasks.Count</div>
                </div>
            </div>
        </div>
        @foreach (var col in _columns)
        {
            <div class="col">
                <div class="card text-center">
                    <div class="card-body py-2">
                        <div class="fw-bold">@col</div>
                        <div class="fs-5">@GetTasksForColumn(col).Count</div>
                    </div>
                </div>
            </div>
        }
        <div class="col">
            <div class="card text-center">
                <div class="card-body py-2">
                    <div class="fw-bold">Overdue</div>
                    <div class="fs-5 text-danger">@_allTasks.Count(t => t.DueDate < DateTime.Today)</div>
                </div>
            </div>
        </div>
    </div>

    <!-- Search Bar -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title…"
               @bind="_searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="row g-3">
        @for (int i = 0; i < _columns.Length; i++)
        {
            var colIndex = i;
            var colName = _columns[colIndex];
            var tasks = GetFilteredTasksForColumn(colName);

            <div class="col-md-4">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@colName</strong>
                        <span class="badge bg-secondary">@tasks.Count</span>
                    </div>
                    <div class="card-body d-flex flex-column gap-2" style="min-height:200px;">
                        @foreach (var task in tasks)
                        {
                            <div class="card shadow-sm">
                                <div class="card-body p-2">
                                    <div class="fw-semibold mb-1">@task.Title</div>
                                    <div class="d-flex justify-content-between align-items-center mb-1">
                                        <small class="text-muted">@task.Assignee</small>
                                        <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
                                    </div>
                                    <div class="d-flex justify-content-between align-items-center">
                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                        <div>
                                            @if (colIndex > 0)
                                            {
                                                <button class="btn btn-outline-secondary btn-sm me-1"
                                                        disabled="@_moving"
                                                        @onclick="() => MoveTaskAsync(task.Id, _columns[colIndex - 1])">
                                                    ← Move Left
                                                </button>
                                            }
                                            @if (colIndex < _columns.Length - 1)
                                            {
                                                <button class="btn btn-outline-secondary btn-sm"
                                                        disabled="@_moving"
                                                        @onclick="() => MoveTaskAsync(task.Id, _columns[colIndex + 1])">
                                                    Move Right →
                                                </button>
                                            }
                                        </div>
                                    </div>
                                </div>
                            </div>
                        }

                        <!-- Add Task Form / Button -->
                        @if (_addingToColumn == colName)
                        {
                            <div class="card border-primary mt-auto">
                                <div class="card-body p-2">
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Title" @bind="_newTitle" />
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Assignee" @bind="_newAssignee" />
                                    <select class="form-select form-select-sm mb-1" @bind="_newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm mb-2"
                                           @bind="_newDueDate" />
                                    @if (_saveError is not null)
                                    {
                                        <div class="text-danger small mb-1">@_saveError</div>
                                    }
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-primary btn-sm" disabled="@_saving"
                                                @onclick="SaveNewTaskAsync">
                                            @(_saving ? "Saving…" : "Save")
                                        </button>
                                        <button class="btn btn-outline-secondary btn-sm"
                                                disabled="@_saving" @onclick="CancelAdd">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                        else
                        {
                            <button class="btn btn-outline-primary btn-sm mt-auto"
                                    @onclick="() => StartAdd(colName)">+ Add Task</button>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private string? _errorMessage;
    private string _searchText = string.Empty;

    // Move state
    private bool _moving;

    // Add-task form state
    private string? _addingToColumn;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);
    private bool _saving;
    private string? _saveError;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async Task LoadTasksAsync()
    {
        _loading = true;
        _errorMessage = null;

        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetTasksForColumn(string status) =>
        _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredTasksForColumn(string status)
    {
        var tasks = _allTasks.Where(t => t.Status == status);

        if (!string.IsNullOrWhiteSpace(_searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase));
        }

        return tasks.ToList();
    }

    private static string GetPriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        _moving = true;

        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _allTasks.First(t => t.Id == taskId);
            _allTasks[_allTasks.IndexOf(task)] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _moving = false;
        }
    }

    private void StartAdd(string column)
    {
        _addingToColumn = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
        _saveError = null;
    }

    private void CancelAdd()
    {
        _addingToColumn = null;
        _saveError = null;
    }

    private async Task SaveNewTaskAsync()
    {
        if (string.IsNullOrWhiteSpace(_newTitle))
        {
            _saveError = "Title is required.";
            return;
        }

        _saving = true;
        _saveError = null;

        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);
            // The service creates tasks; place them in the column where the form was opened.
            _allTasks.Add(created with { Status = _addingToColumn! });
            _addingToColumn = null;
        }
        catch (Exception ex)
        {
            _saveError = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}

